import re
import os
from pathlib import Path
import glob

def task_func(directory_path: str, regex_pattern: str = r'\(.+?\)|\w') -> dict:
    directory = Path(directory_path)

    if not directory.exists() or not directory.is_dir():
        return {}

    result = {}

    for file_path in sorted(directory.iterdir(), key=lambda p: p.name):
        if not file_path.is_file():
            continue

        try:
            content = file_path.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue

        matches = []
        for item in re.findall(regex_pattern, content):
            if isinstance(item, tuple):
                value = next((part for part in item if part), None)
                if value is None:
                    value = next((part for part in item if part is not None), None)
                if value is not None:
                    matches.append(value)
            else:
                if len(item) >= 2 and item.startswith("(") and item.endswith(")"):
                    matches.append(item[1:-1])
                else:
                    matches.append(item)

        result[file_path.name] = matches

    return result

import urllib.request
import zipfile
import os
import urllib.error


def task_func(
    url: str,
    save_path: str = "downloaded_file.zip",
    extract_path: str = "extracted_files",
) -> str:
    error_message = None
    cleanup_error = None

    def _safe_extract(zf: zipfile.ZipFile, destination: str) -> None:
        abs_destination = os.path.abspath(destination)
        for member in zf.infolist():
            member_path = os.path.abspath(os.path.join(destination, member.filename))
            try:
                common = os.path.commonpath([abs_destination, member_path])
            except ValueError as exc:
                raise OSError(f"Unsafe ZIP entry detected: {member.filename}") from exc
            if common != abs_destination:
                raise OSError(f"Unsafe ZIP entry detected: {member.filename}")
        zf.extractall(destination)

    try:
        os.makedirs(extract_path, exist_ok=True)

        with urllib.request.urlopen(url) as response, open(save_path, "wb") as out_file:
            while True:
                chunk = response.read(8192)
                if not chunk:
                    break
                out_file.write(chunk)

        with zipfile.ZipFile(save_path, "r") as zf:
            _safe_extract(zf, extract_path)

    except urllib.error.URLError as exc:
        reason = getattr(exc, "reason", exc)
        error_message = f"URL Error: {reason}"
    except ValueError as exc:
        error_message = f"URL Error: {exc}"
    except zipfile.BadZipFile:
        error_message = "ZIP Error: Corrupted or invalid ZIP file."
    except OSError as exc:
        error_message = f"File Error: {exc}"
    except Exception as exc:
        error_message = f"Error: {exc}"
    finally:
        if os.path.exists(save_path):
            try:
                os.remove(save_path)
            except OSError as exc:
                cleanup_error = (
                    f"File Error: Failed to delete temporary ZIP file: {exc}"
                )

    if error_message is not None:
        return error_message
    if cleanup_error is not None:
        return cleanup_error
    return extract_path

