def task_func(content):
    text = "" if content is None else str(content)
    tokens = nltk.word_tokenize(text)
    word_tokens = [token for token in tokens if any(ch.isalnum() for ch in token)]

    if len(word_tokens) <= 1:
        return {}

    tagged_tokens = nltk.pos_tag(word_tokens[:-1])
    return dict(Counter(tag for _, tag in tagged_tokens))

