import os
from pathlib import Path
import pandas as pd
import docx


def task_func(source_directory: str, target_directory: str) -> int:
    source_path = Path(source_directory)
    target_path = Path(target_directory)

    if not source_path.exists() or not source_path.is_dir():
        raise FileNotFoundError(f"Source directory does not exist: {source_directory}")

    target_path.mkdir(parents=True, exist_ok=True)

    supported_extensions = {".txt", ".docx", ".xlsx", ".csv"}

    source_files = sorted(
        (
            path
            for path in source_path.iterdir()
            if path.is_file() and path.suffix.lower() in supported_extensions
        ),
        key=lambda path: path.name.lower(),
    )

    pending_writes: list[tuple[Path, list[str]]] = []
    for file_path in source_files:
        try:
            texts = _extract_text_entries(file_path)
        except Exception:
            continue
        pending_writes.append((target_path / f"{file_path.stem}.csv", texts))

    converted_count = 0
    for output_path, texts in pending_writes:
        try:
            pd.DataFrame({"Text": texts}).to_csv(output_path, index=False)
        except Exception:
            continue
        converted_count += 1

    return converted_count


def _extract_text_entries(file_path: Path) -> list[str]:
    suffix = file_path.suffix.lower()

    if suffix == ".txt":
        return _extract_from_txt(file_path)
    if suffix == ".docx":
        return _extract_from_docx(file_path)
    if suffix == ".xlsx":
        return _extract_from_xlsx(file_path)
    if suffix == ".csv":
        return _extract_from_csv(file_path)

    return []


def _extract_from_txt(file_path: Path) -> list[str]:
    content = file_path.read_text(encoding="utf-8", errors="replace")
    return content.splitlines()


def _extract_from_docx(file_path: Path) -> list[str]:
    document = docx.Document(os.fspath(file_path))
    texts: list[str] = []

    for paragraph in document.paragraphs:
        texts.append(paragraph.text.strip())

    for table in document.tables:
        for row in table.rows:
            row_text = " ".join(
                cell.text.strip() for cell in row.cells if cell.text.strip()
            ).strip()
            texts.append(row_text)

    return texts


def _extract_from_xlsx(file_path: Path) -> list[str]:
    try:
        sheets = pd.read_excel(
            os.fspath(file_path), sheet_name=None, header=None, dtype=object
        )
    except pd.errors.EmptyDataError:
        return []

    texts: list[str] = []
    for sheet in sheets.values():
        if sheet.empty:
            continue
        for row in sheet.itertuples(index=False, name=None):
            row_text = " ".join(
                value for value in (_normalize_cell_value(cell) for cell in row) if value
            ).strip()
            texts.append(row_text)

    return texts


def _extract_from_csv(file_path: Path) -> list[str]:
    try:
        df = pd.read_csv(
            os.fspath(file_path),
            header=None,
            dtype=object,
            keep_default_na=False,
        )
    except pd.errors.EmptyDataError:
        return []

    texts: list[str] = []
    if df.empty:
        return texts

    for row in df.itertuples(index=False, name=None):
        row_text = " ".join(
            value for value in (_normalize_cell_value(cell) for cell in row) if value
        ).strip()
        texts.append(row_text)

    return texts


def _normalize_cell_value(value) -> str:
    if pd.isna(value):
        return ""
    return str(value).replace("\r\n", "\n").replace("\r", "\n").strip()

import pytz
import numpy as np
from dateutil.parser import parse
import math
MOON_PHASES_YEARS = np.array([1987, 1994, 2001, 2008, 2015, 2022])

from datetime import datetime, timedelta
import calendar


def _safe_localize(tz, naive_dt):
    try:
        return tz.localize(naive_dt, is_dst=None)
    except pytz.AmbiguousTimeError:
        return tz.localize(naive_dt, is_dst=True)
    except pytz.NonExistentTimeError:
        return tz.localize(naive_dt + timedelta(hours=1), is_dst=True)


def _clamp_day(year, month, day):
    return min(day, calendar.monthrange(year, month)[1])


def _julian_day(dt):
    dt_utc = dt.astimezone(pytz.utc)
    year = dt_utc.year
    month = dt_utc.month
    day = (
        dt_utc.day
        + (dt_utc.hour
           + (dt_utc.minute
              + (dt_utc.second + dt_utc.microsecond / 1_000_000.0) / 60.0) / 60.0) / 24.0
    )

    if month <= 2:
        year -= 1
        month += 12

    a = year // 100
    b = 2 - a + a // 4

    return (
        math.floor(365.25 * (year + 4716))
        + math.floor(30.6001 * (month + 1))
        + day
        + b
        - 1524.5
    )


def _reference_year_for_cycle(year):
    years = np.asarray(MOON_PHASES_YEARS, dtype=int)
    if years.size == 0:
        return int(year)

    if years.size > 1:
        cycle = int(round(float(np.median(np.diff(years)))))
    else:
        cycle = 7

    if cycle <= 0:
        cycle = 7

    base_year = int(years[0])
    return base_year + ((int(year) - base_year) % cycle)


def task_func(date_str, from_tz, to_tz):
    try:
        dt = parse(date_str)
    except Exception as exc:
        raise ValueError(f"Invalid date string: {date_str!r}") from exc

    try:
        src_tz = pytz.timezone(from_tz)
    except Exception as exc:
        raise ValueError(f"Invalid from_tz: {from_tz!r}") from exc

    try:
        dst_tz = pytz.timezone(to_tz)
    except Exception as exc:
        raise ValueError(f"Invalid to_tz: {to_tz!r}") from exc

    if dt.tzinfo is None:
        dt = _safe_localize(src_tz, dt)
    else:
        dt = dt.astimezone(src_tz)

    local_dt = dt.astimezone(dst_tz)

    reference_year = _reference_year_for_cycle(local_dt.year)
    safe_day = _clamp_day(reference_year, local_dt.month, local_dt.day)

    ref_naive = datetime(
        reference_year,
        local_dt.month,
        safe_day,
        local_dt.hour,
        local_dt.minute,
        local_dt.second,
        local_dt.microsecond,
    )
    ref_local = _safe_localize(dst_tz, ref_naive)

    jd = _julian_day(ref_local)

    # Moon illumination in [0, 1]: 0 = new moon, 1 = full moon.
    synodic_month = 29.530588853
    new_moon_jd = 2451550.1
    age = ((jd - new_moon_jd) % synodic_month) / synodic_month
    illumination = 0.5 * (1.0 - math.cos(2.0 * math.pi * age))

    return float(max(0.0, min(1.0, illumination)))

import numpy as np
import secrets
import hashlib
import base64

def task_func(num, from_base, to_base, alphabet):
    if from_base < 2 or to_base < 2:
        raise ValueError("from_base and to_base must be at least 2")

    if not isinstance(num, str) or num == "":
        raise ValueError("num must be a non-empty string")

    if not isinstance(alphabet, str) or len(alphabet) != 64 or len(set(alphabet)) != 64:
        raise ValueError("alphabet must be a string of 64 unique characters")

    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~"
    if from_base > len(digits) or to_base > len(digits):
        raise ValueError("base too large to convert")

    def parse_number(s, base):
        sign = 1
        if s[0] in "+-":
            if len(s) == 1:
                raise ValueError("num contains characters not valid in the specified from_base")
            if s[0] == "-":
                sign = -1
            s = s[1:]

        lookup = {ch: i for i, ch in enumerate(digits[:base])}
        if base <= 36:
            for i, ch in enumerate(digits[10:36], start=10):
                lookup[ch.lower()] = i

        value = 0
        for ch in s:
            if ch not in lookup:
                raise ValueError("num contains characters not valid in the specified from_base")
            value = value * base + lookup[ch]

        return sign * value

    def int_to_base(value, base):
        if value == 0:
            return "0"
        sign = "-" if value < 0 else ""
        n = abs(value)
        out = []
        while n:
            n, rem = divmod(n, base)
            out.append(digits[rem])
        return sign + "".join(reversed(out))

    value = parse_number(num, from_base)
    converted = int_to_base(value, to_base)

    salt = secrets.token_hex(16)

    payload = f"{converted}|{salt}".encode("utf-8")
    digest = hashlib.sha256(payload).digest()

    standard_b64 = base64.b64encode(digest).decode("ascii")
    translation = str.maketrans(
        "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/",
        alphabet,
    )
    encoded_hash = standard_b64.translate(translation)

    return encoded_hash, salt

